.text
.ent main
    
main:
jal Configuracion_Pins
jal Configuracion_SPI
jal Configuracion_SSD1306
jal Configuracion_UART
jal InicializacionRow 
jal Borrar_Row

li $t0, 0 # Inicializo Flag Guardar en Flash
sb $t0, Flag_Guardar
li $s0, 0 

la $a0, img_menu
jal imprimir_bitmap
	
    
Menu:
	
	lb $t0, Flag_Guardar
	beq $t0, $zero, No_Guardar
	
	jal Guardar_Flash
	li $t0, 0
	sb $t0, Flag_Guardar
	No_Guardar:
    
    move $a0, $s0
    jal funcion_menu 

    move $s0, $v0
    move $t1, $v1
    # si $ v1 es 0 se toco el boton aceptar
    
    bnez $v1, Menu 
    
    
    beq $s0, 0, Ejecutar_piano
    beq $s0, 1, Ejecutar_grabacion
    beq $s0, 2, Ejecutar_melodiaFlash
    beq $s0, 3, Ejecutar_melodia1
    beq $s0, 4, Ejecutar_melodia2
    beq $s0, 5, Ejecutar_melodia3

	Ejecutar_piano:
	jal funcion_piano
	
	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu

	Ejecutar_grabacion:
	jal funcion_grabacion
	
	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu

	Ejecutar_melodiaFlash:
	li $a0, 0xBD07FE00 # dir virtual inicio flash
	jal funcion_melodia
	
	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu
	
	Ejecutar_melodia1:
	la $a0, Melodia_1
	jal funcion_melodia

	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu
	
	Ejecutar_melodia2:
	la $a0, Melodia_2
	jal funcion_melodia
	
	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu
    
	Ejecutar_melodia3:
	la $a0, Melodia_3
	jal funcion_melodia
	
	la $a0, img_menu
	jal imprimir_bitmap
    
	li $s0, 0 
	j Menu
	
    
     
.end main






